import type { Metadata } from "next";

export const SITE_URL = "https://portfolio.mgarciap.workers.dev";
export const SITE_NAME = "Moisés García";

// Generated by app/opengraph-image.tsx; named here because a page-level openGraph
// object replaces the one inherited from the layout, image included.
export const SHARE_IMAGE = "/opengraph-image";

/**
 * Per-page metadata: unique title and description, a canonical URL and matching
 * Open Graph / Twitter tags. `path` is relative to `metadataBase`.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      siteName: SITE_NAME,
      type: "website",
      locale: "es_ES",
      images: [{ url: SHARE_IMAGE, width: 1200, height: 630, alt: title }],
    },
    twitter: { card: "summary_large_image", title, description, images: [SHARE_IMAGE] },
  };
}
